const inputItem = items[0].json;
const newItems = [];

// Iteramos sobre cada par [clave, valor] del objeto de entrada
for (const [key, value] of Object.entries(inputItem)) {

  // --- FILTRO AÑADIDO AQUÍ ---
  // Solo procesamos las claves que NO empiezan con "summary_marker:"
  if (!key.startsWith('summary_marker:')) {

    // Si la clave es de una conversación, la añadimos a la lista para procesar.
    newItems.push({
      json: {
        "keyPattern": key,
        "chatHistory": value
      }
    });
  }
}

// Devolvemos el array de nuevos ítems, que ahora solo contiene conversaciones reales.
return newItems;

const items = $input.all();

return items.map(item => {
  // Soporte para cuando los datos están dentro de item.json (caso común en n8n)
  const source = item.json || item;

  const historialCompleto = source.chatHistory || [];
  const originalKey = source.keyPattern || '';
  const indiceGuardado = source.data ? parseInt(source.data) : 0;
  const longitudTotal = historialCompleto.length;

  // Manejo del nuevo campo de contacto (usando clave dinámica)
  let contactDataParsed = null;
  const rawContactData = source[originalKey];
  if (rawContactData && typeof rawContactData === 'string') {
    try {
      contactDataParsed = JSON.parse(rawContactData);
    } catch (e) {
      console.error("Error al parsear datos de contacto para", originalKey, ":", e);
    }
  }

  // Validación básica
  if (!Array.isArray(historialCompleto) || indiceGuardado >= longitudTotal) {
    return null;
  }

  // Obtenemos mensajes nuevos en orden inverso
  const mensajesNuevos = historialCompleto.slice(0, longitudTotal - indiceGuardado).reverse();

  const formattedChatHistory = mensajesNuevos.map(messageString => {
    try {
      const messageObject = JSON.parse(messageString);
      const type = messageObject.type;
      const content = messageObject.data.content.trim();
      if (type === 'human') return `human: ${content}`;
      if (type === 'ai') return `AI: ${content}`;
      return '';
    } catch (e) {
      return '';
    }
  }).filter(Boolean);

  const tlf = originalKey.split('@')[0];

  const result = {
    Tlf: tlf,
    keyPattern: originalKey,
    longitudTotal: longitudTotal,
    chatHistoryParsed: formattedChatHistory.join('\n\n'),
    contactData: contactDataParsed
  };

  // Log de depuración opcional
  console.log("Resultado generado:", result);

  return { json: result };
}).filter(Boolean);
